VALUES ('liturgical-calendar-mcp', 'Liturgical Calendar MCP Server', 'Lets an AI agent query the Roman Catholic liturgical calendar.', 'A Model Context Protocol server in front of the Liturgical Calendar API, exposing liturgical dates, seasons, feasts, saints and rankings as a structured toolset for any MCP client — so an assistant can answer ''what colour are the vestments on the third Sunday of Advent 2027?'' by calling a tool instead of guessing, which unaided models reliably do badly.', 'https://github.com/CatholicOS/liturgical-calendar-mcp', NULL, 'https://github.com/CatholicOS/liturgical-calendar-mcp', 'mcp', 'api', NULL, '[]', 'free', 'Open source; self-hosted or run from the repository.', 1, 'Apache-2.0', 'none', 'unknown', 1, '["Liturgical Calendar","AI & Search","Developer Tools"]', '["en"]', 'published', 0, NULL, 'Catholic Digital Commons Foundation', 'https://github.com/CatholicOS')
