VALUES ('ontokit-api', 'OntoKit API', 'Collaborative OWL ontology curation, as a FastAPI service.', 'A Python service for curating OWL ontologies collaboratively, published on PyPI as `ontokit`. It is the machinery behind the foundation''s semantic work rather than a Catholic dataset in itself, but it is the piece you would reuse if you were modelling any structured body of doctrine or church data.', 'https://github.com/CatholicOS/ontokit-api', NULL, 'https://github.com/CatholicOS/ontokit-api', 'api', 'api', NULL, '[]', 'free', 'Open source; self-hosted or run from the repository.', 1, NULL, 'unknown', 'unknown', 1, '["Developer Tools","AI & Search"]', '["en"]', 'published', 0, NULL, 'Catholic Digital Commons Foundation', 'https://github.com/CatholicOS')
