INSERT INTO apis (slug, name, tagline, description, homepage_url, docs_url, repo_url, kind, track, launched_at, platforms, pricing, pricing_note, open_source, license, auth, cors, official, categories, languages, status, deprecated, deprecated_note, source, source_url)
VALUES ('mediawiki-extensions-semanticsearch', 'SemanticSearch for MediaWiki', 'Hybrid keyword and semantic search for MediaWiki — early scaffold.', 'Adds sentence-transformer embeddings alongside CirrusSearch''s BM25 keyword retrieval and rank-fuses the two, using OpenSearch k-NN. Its own README calls the current release a scaffold, so treat it as a project to watch rather than one to deploy — but the approach is the right one for searching a wiki of magisterial texts, where the wording a reader knows is rarely the wording on the page.', 'https://github.com/CatholicOS/mediawiki-extensions-SemanticSearch', NULL, 'https://github.com/CatholicOS/mediawiki-extensions-SemanticSearch', 'library', 'api', NULL, '[]', 'free', 'Open source; self-hosted or run from the repository.', 1, 'GPL-3.0', 'none', 'unknown', 1, '["AI & Search","Developer Tools"]', '["en"]', 'published', 0, NULL, 'Catholic Digital Commons Foundation', 'https://github.com/CatholicOS')
