VALUES ('cecdr', 'CECDR — Ecclesiastical Circumscriptions', 'Canonical IDs for every diocese, eparchy and prelature.', 'The Common Ecclesiastical Circumscription Data Repository: stable identifiers for the circumscriptions of the Catholic Church — Latin dioceses and archdioceses, Eastern eparchies, archeparchies and exarchates, territorial prelatures and abbacies, apostolic vicariates and prefectures, military and personal ordinariates, personal prelatures and missions. If you have ever tried to join two datasets on diocese name, this is the thing that was missing.', 'https://github.com/CatholicOS/cecdr', NULL, 'https://github.com/CatholicOS/cecdr', 'dataset', 'api', NULL, '[]', 'free', 'Open source; self-hosted or run from the repository.', 1, 'Apache-2.0', 'none', 'unknown', 1, '["Church Data"]', '["la","en"]', 'published', 0, NULL, 'Catholic Digital Commons Foundation', 'https://github.com/CatholicOS')
